{"implementation":"import math

def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "nodes" not in case or "required_symbols" not in case:
        raise ValueError("missing required case field")
    nodes = case["nodes"]
    required_symbols = case["required_symbols"]
    if not isinstance(nodes, list) or not nodes:
        raise ValueError("nodes must be a nonempty list")
    if not isinstance(required_symbols, list):
        raise ValueError("required_symbols must be a list")
    for symbol in required_symbols:
        if not isinstance(symbol, str):
            raise ValueError("required symbol must be a string")

    by_id = {}
    ordered_ids = []
    for node in nodes:
        if not isinstance(node, dict):
            raise ValueError("node must be an object")
        for field in ("id", "parent", "symbol", "depth", "removable", "utility"):
            if field not in node:
                raise ValueError("node missing required field")
        node_id = node["id"]
        parent = node["parent"]
        depth = node["depth"]
        utility = node["utility"]
        if not isinstance(node_id, str) or not isinstance(node["symbol"], str):
            raise ValueError("node id and symbol must be strings")
        if parent is not None and not isinstance(parent, str):
            raise ValueError("parent must be a string or null")
        if isinstance(depth, bool) or not isinstance(depth, int) or depth < 0:
            raise ValueError("depth must be a nonnegative integer")
        if not isinstance(node["removable"], bool):
            raise ValueError("removable must be boolean")
        if isinstance(utility, bool) or not isinstance(utility, (int, float)) or not math.isfinite(utility):
            raise ValueError("utility must be finite")
        if node_id in by_id:
            raise ValueError("duplicate node id")
        by_id[node_id] = node
        ordered_ids.append(node_id)

    roots = [node_id for node_id in ordered_ids if by_id[node_id]["parent"] is None]
    if len(roots) != 1:
        raise ValueError("tree must have exactly one root")
    root_id = roots[0]
    if by_id[root_id]["depth"] != 0:
        raise ValueError("root depth must be zero")

    children = {node_id: [] for node_id in ordered_ids}
    for node_id in ordered_ids:
        node = by_id[node_id]
        parent = node["parent"]
        if parent is None:
            continue
        if parent not in by_id:
            raise ValueError("unknown parent")
        if node["depth"] != by_id[parent]["depth"] + 1:
            raise ValueError("inconsistent parent depth")
        children[parent].append(node_id)

    required = set(required_symbols)
    represented = {symbol: 0 for symbol in required_symbols}
    for node_id in ordered_ids:
        symbol = by_id[node_id]["symbol"]
        if symbol in represented:
            represented[symbol] += 1
    if any(represented[symbol] == 0 for symbol in required_symbols):
        raise ValueError("required symbol is not represented")

    candidates = sorted(ordered_ids, key=lambda node_id: (-by_id[node_id]["depth"], node_id))
    retained = set(ordered_ids)
    removed = []
    for node_id in candidates:
        node = by_id[node_id]
        if node_id == root_id or not node["removable"]:
            continue
        if node["symbol"] in required:
            continue
        if any(child_id in retained for child_id in children[node_id]):
            continue
        symbol = node["symbol"]
        if symbol in represented and represented[symbol] <= 1:
            continue
        retained.remove(node_id)
        if symbol in represented:
            represented[symbol] -= 1
        removed.append(node_id)

    return {
        "removed_node_ids": removed,
        "retained_node_ids": sorted(retained),
    }
"}
